        </select>
    </header>

    <div id="chatBox" class="flex-1 overflow-y-auto space-y-3 pr-2 mb-4 text-sm">
        <div class="bg-slate-900 border border-slate-800/80 p-3 rounded-xl max-w-[85%] text-slate-300 shadow-sm">
            Bhai, apna local backend server start karke message bhejo! (Endpoints OpenAI-compatible format use kar rahe hain).
        </div>
    </div>

    <form id="chatForm" class="flex gap-2 bg-slate-900/50 p-2 rounded-xl border border-slate-800">
        <input type="text" id="userInput" placeholder="Ask your local AI model..." class="flex-1 bg-transparent border-none px-3 py-2 text-sm text-slate-100 placeholder-slate-500 focus:outline-none" required>
        <button type="submit" class="bg-cyan-600 hover:bg-cyan-500 text-white px-5 py-2 rounded-lg text-sm font-medium transition shadow-lg shadow-cyan-950">Send</button>
    </form>

    <script>
        const chatBox = document.getElementById('chatBox');
        const chatForm = document.getElementById('chatForm');
        const userInput = document.getElementById('userInput');
        const modelSelect = document.getElementById('modelSelect');

        chatForm.onsubmit = async (e) => {
            e.preventDefault();
            const text = userInput.value.trim();
            const selectedModel = modelSelect.value;
            if (!text) return;

