                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        model: selectedModel,
                        messages: [{ role: 'user', content: text }]
                    })
                });

                const data = await res.json();
                const reply = data.choices?.[0]?.message?.content || data.error?.message || "No response received.";

                document.getElementById(loadingId).remove();
                chatBox.innerHTML += `<div class="bg-slate-900 border border-slate-800 p-3 rounded-xl max-w-[85%] text-slate-200">${reply}</div>`;
            } catch (err) {
                document.getElementById(loadingId).remove();
                chatBox.innerHTML += `<div class="bg-red-950/50 border border-red-900/40 p-3 rounded-xl max-w-[85%] text-red-300">Connection failed! Ensure your local backend is running on port 8080.</div>`;
            }
            chatBox.scrollTop = chatBox.scrollHeight;
        };
    </script>
</body>
</html>
```

