Complete working single-file HTML app using Pollinations free text API:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sasta AI All-in-One</title>
    <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4"></script>
</head>
<body class="bg-slate-950 text-slate-100 flex flex-col h-screen max-w-2xl mx-auto p-4">
    <div class="flex items-center justify-between border-b border-slate-800 pb-3 mb-4">
        <h1 class="text-lg font-bold text-cyan-400">⚡ Sasta AI Chat</h1>
        <select id="model" class="bg-slate-900 border border-slate-700 text-xs rounded px-2 py-1 text-slate-300">
            <option value="openai">Pollinations: OpenAI</option>
            <option value="mistral">Pollinations: Mistral</option>
            <option value="deepseek">Pollinations: DeepSeek</option>
        </select>
    </div>
    <div id="chat" class="flex-1 overflow-y-auto space-y-3 mb-4 text-sm">
        <div class="bg-slate-900 border border-slate-800 p-2.5 rounded max-w-[80%] text-slate-300">Model select karo aur poochho!</div>
    </div>
    <div class="flex gap-2">
        <input id="input" type="text" placeholder="Type message..." class="flex-1 bg-slate-900 border border-slate-700 rounded px-3 py-2 text-sm focus:outline-none">
        <button onclick="sendMsg()" class="bg-cyan-500 hover:bg-cyan-600 text-slate-950 font-bold px-4 py-2 rounded text-sm cursor-pointer">Send</button>
    </div>
    <script>
        async function sendMsg() {
            const input = document.getElementById('input');
            const chat = document.getElementById('chat');
            const model = document.getElementById('model').value;
            const text = input.value.trim();
            if(!text) return;

            chat.innerHTML += `<div class="bg-slate-800 p-2.5 rounded ml-auto max-w-[80%]">${text}</div>`;
            input.value = '';
            chat.scrollTop = chat.scrollHeight;

            const resDiv = document.createElement('div');
            resDiv.className = 'bg-slate-900 border border-slate-800 p-2.5 rounded max-w-[80%] text-slate-300';
            resDiv.innerText = 'Thinking...';
            chat.appendChild(resDiv);
            chat.scrollTop = chat.scrollHeight;

            try {
                const res = await fetch('https://text.pollinations.ai/', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({messages: [{role: 'user', content: text}], model: model})
                });
                resDiv.innerText = await res.text();
            } catch(e) {
                resDiv.innerText = 'Error: ' + e.message;
            }
            chat.scrollTop = chat.scrollHeight;
        }
        document.getElementById('input').addEventListener('keypress', e => { if(e.key==='Enter') sendMsg(); });
    </script>
</body>
</html>
```

